text:
onMouseDown(event) {
  event.stopPropagation();
  if (this.mDate) {
    this.calendarView.selectedDay = this.mDate;
  }
}

onDblClick(event) {
  event.stopPropagation();
  this.calendarView.controller.createNewEvent();
}

onClick(event) {
  if (event.button != 0) {
    return;
  }

  if (!(event.ctrlKey || event.metaKey)) {
    this.calendarView.setSelectedItems([]);
  }
}
